PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE Locations (id INTEGER PRIMARY KEY AUTOINCREMENT, locationName TEXT NOT NULL, x INTEGER, y INTEGER, z INTEGER);
CREATE TABLE AccessPoints (id INTEGER PRIMARY KEY AUTOINCREMENT, BSSID TEXT NOT NULL, SSID TEXT NOT NULL, AvgRSSI INTEGER, LocationID INTEGER, FOREIGN KEY(LocationID) REFERENCES Locations(id));
DELETE FROM sqlite_sequence;
COMMIT;